/**
 * Domain entities. Field names are camelCase here and snake_case in PostgreSQL;
 * the Postgres data store converts between the two. Money is always integer cents.
 * IDs are UUIDs generated by the application so every data store behaves identically.
 */

export type ID = string;
export type ISODate = string;

export interface Timestamps {
  createdAt: ISODate;
  updatedAt: ISODate;
}

// ─── Identity ────────────────────────────────────────────────────────────────
export type UserStatus = 'active' | 'pending_verification' | 'locked' | 'disabled';

export interface User extends Timestamps {
  id: ID;
  email: string;
  passwordHash: string;
  fullName: string;
  phone: string | null;
  status: UserStatus;
  emailVerifiedAt: ISODate | null;
  mfaEnabled: boolean;
  failedLogins: number;
  lockedUntil: ISODate | null;
  marketingConsent: boolean;
  locationSharing: boolean;
  deletedAt: ISODate | null;
}

export type RoleKey =
  | 'consumer'
  | 'merchant_admin'
  | 'store_employee'
  | 'platform_admin'
  | 'platform_support';

export interface UserRole {
  id: ID;
  userId: ID;
  role: RoleKey;
  /** Scopes merchant roles to one business. */
  businessId: ID | null;
  createdAt: ISODate;
}

export interface Session {
  id: ID;
  userId: ID;
  tokenHash: string;
  expiresAt: ISODate;
  revokedAt: ISODate | null;
  ip: string | null;
  userAgent: string | null;
  createdAt: ISODate;
}

export interface AuthToken {
  id: ID;
  userId: ID;
  purpose: 'verify_email' | 'reset_password' | 'mfa';
  tokenHash: string;
  expiresAt: ISODate;
  consumedAt: ISODate | null;
  attempts: number;
  createdAt: ISODate;
}

// ─── Businesses & stores ────────────────────────────────────────────────────
export type BusinessStatus = 'pending' | 'approved' | 'rejected' | 'suspended';

export interface Business extends Timestamps {
  id: ID;
  legalName: string;
  dbaName: string | null;
  einLast4: string | null;
  ownerUserId: ID;
  status: BusinessStatus;
  contactEmail: string;
  contactPhone: string | null;
  reviewNotes: string | null;
  reviewedBy: ID | null;
  reviewedAt: ISODate | null;
}

export const STORE_TYPES = [
  'grocery',
  'convenience',
  'gas_station',
  'pharmacy',
  'specialty',
  'retail',
] as const;
export type StoreType = (typeof STORE_TYPES)[number];

export type StoreStatus = 'pending' | 'active' | 'suspended' | 'closed';

export interface Store extends Timestamps {
  id: ID;
  businessId: ID;
  marketId: ID | null;
  name: string;
  slug: string;
  storeType: StoreType;
  description: string;
  addressLine1: string;
  city: string;
  county: string | null;
  state: string;
  zip: string;
  latitude: number;
  longitude: number;
  serviceRadiusMi: number;
  phone: string | null;
  email: string | null;
  website: string | null;
  services: string[];
  pickupEnabled: boolean;
  deliveryEnabled: boolean;
  deliveryFeeCents: number;
  status: StoreStatus;
  verifiedAt: ISODate | null;
  deletedAt: ISODate | null;
}

export interface StoreHours {
  id: ID;
  storeId: ID;
  /** 0 = Sunday */
  dayOfWeek: number;
  opens: string; // "07:00"
  closes: string; // "22:00"
  closed: boolean;
}

export type StoreStaffRole = 'manager' | 'employee';
export const EMPLOYEE_CAPABILITIES = [
  'inventory.manage',
  'orders.process',
  'orders.view',
  'products.manage',
  'offers.manage',
  'store_orders.manage',
] as const;
export type EmployeeCapability = (typeof EMPLOYEE_CAPABILITIES)[number];

export interface StoreUser {
  id: ID;
  storeId: ID;
  userId: ID;
  staffRole: StoreStaffRole;
  capabilities: EmployeeCapability[];
  createdAt: ISODate;
}

export interface GeographicMarket extends Timestamps {
  id: ID;
  name: string;
  state: string;
  latitude: number;
  longitude: number;
  radiusMi: number;
  status: 'active' | 'planned' | 'paused';
}

// ─── Catalog ────────────────────────────────────────────────────────────────
export interface Category {
  id: ID;
  parentId: ID | null;
  name: string;
  slug: string;
  sort: number;
  icon: string | null;
}

export interface Brand {
  id: ID;
  name: string;
}

export type ProductStatus = 'active' | 'pending_review' | 'rejected' | 'archived';

export interface Product extends Timestamps {
  id: ID;
  categoryId: ID;
  brandId: ID | null;
  name: string;
  slug: string;
  description: string;
  upc: string | null;
  sku: string;
  unit: string; // "each", "case", "lb"
  size: string | null; // "20 fl oz"
  attributes: Record<string, string | number | boolean>;
  images: string[];
  status: ProductStatus;
  createdByStoreId: ID | null;
  deletedAt: ISODate | null;
}

export interface ProductVariant {
  id: ID;
  productId: ID;
  name: string;
  sku: string;
  upc: string | null;
  attributes: Record<string, string | number | boolean>;
}

export type InventorySource = 'manual' | 'csv' | 'bulk' | 'admin' | 'pos';

/** Store-specific listing: price + stock of a catalog product at one store. */
export interface StoreProduct {
  id: ID;
  storeId: ID;
  productId: ID;
  variantId: ID | null;
  storeSku: string | null;
  priceCents: number;
  promoPriceCents: number | null;
  quantity: number;
  lowStockThreshold: number;
  minOrderQty: number;
  maxOrderQty: number | null;
  visible: boolean;
  b2bEnabled: boolean;
  b2bPriceCents: number | null;
  b2bMinQty: number;
  b2bUnit: string; // "case of 24"
  availableFrom: ISODate | null;
  availableUntil: ISODate | null;
  source: InventorySource;
  updatedAt: ISODate;
  createdAt: ISODate;
}

export type StockStatus = 'in_stock' | 'low_stock' | 'out_of_stock';

export interface InventoryEvent {
  id: ID;
  storeProductId: ID;
  storeId: ID;
  delta: number;
  quantityAfter: number;
  reason: string;
  source: InventorySource;
  actorId: ID | null;
  createdAt: ISODate;
}

// ─── Offers ─────────────────────────────────────────────────────────────────
export type DiscountType = 'percent' | 'fixed' | 'bxgy';
export type OfferScope = 'product' | 'category' | 'store';
export type OfferStatus = 'draft' | 'active' | 'paused' | 'expired';

export interface Offer extends Timestamps {
  id: ID;
  storeId: ID;
  name: string;
  description: string;
  scope: OfferScope;
  productId: ID | null;
  categoryId: ID | null;
  discountType: DiscountType;
  /** percent: 0–100, fixed: cents, bxgy: unused */
  discountValue: number;
  buyQty: number | null;
  getQty: number | null;
  startAt: ISODate;
  endAt: ISODate;
  eligibility: 'all' | 'new_customer';
  /** Geographic promotion: only shown to shoppers within this many miles. */
  geoRadiusMi: number | null;
  usageLimit: number | null;
  usageCount: number;
  status: OfferStatus;
}

// ─── Consumer commerce ─────────────────────────────────────────────────────
export interface Address extends Timestamps {
  id: ID;
  userId: ID;
  label: string;
  line1: string;
  city: string;
  state: string;
  zip: string;
  latitude: number | null;
  longitude: number | null;
  isDefault: boolean;
}

export interface Cart {
  id: ID;
  userId: ID;
  updatedAt: ISODate;
  createdAt: ISODate;
}

export interface CartItem {
  id: ID;
  cartId: ID;
  storeProductId: ID;
  quantity: number;
  createdAt: ISODate;
}

export type FulfillmentType = 'pickup' | 'curbside' | 'delivery';

export const ORDER_STATUSES = [
  'pending_payment',
  'confirmed',
  'processing',
  'ready',
  'out_for_delivery',
  'completed',
  'cancelled',
  'payment_failed',
] as const;
export type OrderStatus = (typeof ORDER_STATUSES)[number];

export interface Order extends Timestamps {
  id: ID;
  number: string;
  userId: ID;
  storeId: ID;
  status: OrderStatus;
  fulfillmentType: FulfillmentType;
  deliveryAddress: { line1: string; city: string; state: string; zip: string } | null;
  subtotalCents: number;
  discountCents: number;
  taxCents: number;
  feeCents: number;
  totalCents: number;
  paymentStatus: PaymentStatus;
  idempotencyKey: string | null;
  notes: string | null;
}

export interface OrderItem {
  id: ID;
  orderId: ID;
  storeProductId: ID;
  productId: ID;
  productName: string;
  unitPriceCents: number;
  quantity: number;
  discountCents: number;
  totalCents: number;
  offerId: ID | null;
}

export interface StatusHistory {
  id: ID;
  /** consumer order id or store order id */
  orderId: ID;
  kind: 'consumer' | 'store';
  fromStatus: string | null;
  toStatus: string;
  actorId: ID | null;
  note: string | null;
  createdAt: ISODate;
}

// ─── Store-to-store (B2B) ──────────────────────────────────────────────────
export const STORE_ORDER_STATUSES = [
  'draft',
  'submitted',
  'pending_acceptance',
  'accepted',
  'preparing',
  'ready',
  'completed',
  'rejected',
  'cancelled',
] as const;
export type StoreOrderStatus = (typeof STORE_ORDER_STATUSES)[number];

export interface StoreOrder extends Timestamps {
  id: ID;
  number: string;
  buyerStoreId: ID;
  sellerStoreId: ID;
  status: StoreOrderStatus;
  subtotalCents: number;
  buyerNotes: string | null;
  sellerNotes: string | null;
  createdBy: ID;
  partial: boolean;
}

export interface StoreOrderItem {
  id: ID;
  storeOrderId: ID;
  storeProductId: ID;
  productId: ID;
  productName: string;
  unitLabel: string;
  unitPriceCents: number;
  requestedQty: number;
  acceptedQty: number | null;
  fulfilledQty: number | null;
}

// ─── Payments ──────────────────────────────────────────────────────────────
export type PaymentStatus =
  | 'unpaid'
  | 'authorized'
  | 'captured'
  | 'failed'
  | 'refunded'
  | 'partially_refunded'
  | 'pay_in_store';

export interface Payment extends Timestamps {
  id: ID;
  orderId: ID;
  provider: string;
  providerRef: string | null;
  status: PaymentStatus;
  amountCents: number;
  refundedCents: number;
  cardBrand: string | null;
  cardLast4: string | null;
}

export interface PaymentTransaction {
  id: ID;
  paymentId: ID;
  type: 'authorize' | 'capture' | 'refund' | 'failure' | 'void';
  amountCents: number;
  providerRef: string | null;
  success: boolean;
  message: string | null;
  createdAt: ISODate;
}

// ─── Engagement, ops, audit ────────────────────────────────────────────────
export interface Notification {
  id: ID;
  userId: ID;
  storeId: ID | null;
  type: string;
  title: string;
  body: string;
  link: string | null;
  channel: 'in_app' | 'email' | 'sms';
  readAt: ISODate | null;
  createdAt: ISODate;
}

export interface Favorite {
  id: ID;
  userId: ID;
  storeId: ID | null;
  productId: ID | null;
  createdAt: ISODate;
}

export interface SupportTicket extends Timestamps {
  id: ID;
  userId: ID | null;
  email: string;
  subject: string;
  body: string;
  orderId: ID | null;
  status: 'open' | 'in_progress' | 'resolved';
  category: 'order' | 'account' | 'store' | 'payment' | 'other';
}

export interface SearchEvent {
  id: ID;
  userId: ID | null;
  query: string;
  /** Rounded to ~1 km (2 decimals) for privacy. */
  latRounded: number | null;
  lngRounded: number | null;
  radiusMi: number | null;
  resultCount: number;
  createdAt: ISODate;
}

export interface AnalyticsEvent {
  id: ID;
  name: string;
  schemaVersion: number;
  userId: ID | null;
  storeId: ID | null;
  props: Record<string, unknown>;
  createdAt: ISODate;
}

export interface AuditLog {
  id: ID;
  actorId: ID | null;
  actorEmail: string | null;
  action: string;
  entity: string;
  entityId: ID | null;
  before: unknown;
  after: unknown;
  ip: string | null;
  userAgent: string | null;
  createdAt: ISODate;
}

export interface SystemSetting {
  /** Setting key, e.g. "tax.rates". */
  id: string;
  value: unknown;
  updatedBy: ID | null;
  updatedAt: ISODate;
}

export interface SearchIndexMetadata {
  id: ID;
  entity: 'product' | 'store' | 'store_product';
  entityId: ID;
  indexedAt: ISODate;
  version: number;
}

/** Public projection of a user (never expose hashes). */
export type PublicUser = Omit<User, 'passwordHash' | 'failedLogins' | 'lockedUntil' | 'deletedAt'> & {
  roles: RoleKey[];
  businessIds: ID[];
  storeIds: ID[];
};
